{
  "format_version": 3,
  "flavours": {
    "subject": {
      "id_prefix": "SUB-",
      "body": "required",
      "description": "Fixture subject",
      "use_when": [
        "Fixture root"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    },
    "support": {
      "id_prefix": "SUP-",
      "body": "required",
      "description": "Fixture support",
      "use_when": [
        "Fixture related item"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "amount": {
          "type": "integer"
        },
        "text": {
          "type": "string"
        },
        "flag": {
          "type": "boolean"
        },
        "score": {
          "type": "number"
        },
        "absent": {
          "type": "string"
        },
        "alias": {
          "type": "string"
        },
        "empty": {
          "type": "string"
        }
      }
    },
    "candidate": {
      "id_prefix": "CAND-",
      "body": "required",
      "description": "Fixture candidate under verification",
      "use_when": [
        "Fixture query root"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "likelihood": {
          "type": "integer"
        },
        "consequence": {
          "type": "integer"
        }
      }
    },
    "verification": {
      "id_prefix": "VER-",
      "body": "required",
      "description": "Fixture verification required by a candidate",
      "use_when": [
        "Fixture required fact subject"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    },
    "implementation": {
      "id_prefix": "IMP-",
      "body": "required",
      "description": "Fixture implementation",
      "use_when": [
        "Direct or design-mediated support"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    },
    "context": {
      "description": "Fixture-only contextual need, goal or risk.",
      "use_when": [
        "Declare a context returned with selected ancestry."
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "id_prefix": "CTX-",
      "body": "required",
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "kind": {
          "type": "enum",
          "values": [
            "need",
            "goal",
            "risk"
          ],
          "required": true
        }
      }
    }
  },
  "relations": {
    "supports": {
      "description": "Fixture support relation",
      "source": [
        "support"
      ],
      "target": [
        "subject"
      ],
      "inverse": "supported_by"
    },
    "parent": {
      "description": "Fixture upward ancestry",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "children"
    },
    "decomposes_to": {
      "description": "Fixture decomposition",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "decomposed_from"
    },
    "supersedes": {
      "description": "Fixture supersession",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "superseded_by"
    },
    "requires_verification": {
      "description": "Fixture candidate-to-verification requirement",
      "source": [
        "candidate"
      ],
      "target": [
        "verification"
      ],
      "inverse": "required_by"
    },
    "implements": {
      "description": "Fixture implementation",
      "source": [
        "implementation"
      ],
      "target": [
        "subject",
        "candidate"
      ],
      "inverse": "implemented_by"
    },
    "satisfies": {
      "description": "Fixture satisfying design",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ]
    },
    "context": {
      "description": "Fixture context",
      "source": [
        "subject"
      ],
      "target": [
        "support",
        "context"
      ]
    }
  }
}

{
  "format_version": 1,
  "definitions": [
    {
      "id": "urn:fixture:query:supports",
      "required_fact_sources": [
        "documents"
      ],
      "support_columns": [
        "edge"
      ],
      "source_columns": [
        "support_source"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        },
        "lifecycle": {
          "type": "text"
        },
        "amount": {
          "type": "integer"
        },
        "text": {
          "type": "text"
        },
        "flag": {
          "type": "boolean"
        },
        "score": {
          "type": "number"
        },
        "absent": {
          "type": "text",
          "optional": true
        }
      },
      "parameters": {
        "state": {
          "type": "text",
          "required": true
        }
      },
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?support ?support_source ?edge ?lifecycle ?amount ?text ?flag ?score ?absent WHERE {\n { ?root r:supported_by ?support } UNION { ?support r:supports ?root }\n ?edge <urn:mara:query:source> ?support ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> r:supports .\n BIND(?support AS ?support_source)\n ?support f:status ?lifecycle ; f:amount ?amount ; f:text ?text ; f:flag ?flag ; f:score ?score .\n OPTIONAL { ?support f:absent ?absent }\n FILTER(sameTerm(?state, \"\") || sameTerm(?lifecycle, ?state))\n}"
    },
    {
      "id": "urn:fixture:query:ancestry",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "ancestor": {
          "type": "item",
          "flavours": [
            "subject"
          ]
        },
        "lifecycle": {
          "type": "text"
        }
      },
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?ancestor ?lifecycle WHERE {\n ?root r:parent+ ?ancestor . FILTER(!sameTerm(?root, ?ancestor))\n ?ancestor f:status ?lifecycle\n}"
    },
    {
      "id": "urn:fixture:query:forward",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "support"
      ],
      "columns": {
        "subject": {
          "type": "item",
          "flavours": [
            "subject"
          ]
        }
      },
      "select": "SELECT ?root ?subject WHERE { ?root <urn:mara:relation:supports> ?subject }"
    },
    {
      "id": "urn:fixture:query:optional",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "absent": {
          "type": "text",
          "optional": true
        }
      },
      "select": "SELECT ?root ?absent WHERE { ?root <urn:mara:relation:supported_by> ?support . OPTIONAL { ?support <urn:mara:field:absent> ?absent } }"
    },
    {
      "id": "urn:fixture:query:support-links",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        }
      },
      "support_columns": [
        "edge"
      ],
      "select": "SELECT ?root ?support ?edge WHERE { { ?root <urn:mara:relation:supported_by> ?support } UNION { ?support <urn:mara:relation:supports> ?root } ?edge <urn:mara:query:source> ?support ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:supports> }"
    },
    {
      "id": "urn:fixture:query:root-status",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "state": {
          "type": "text"
        }
      },
      "select": "SELECT ?root ?state WHERE { ?root <urn:mara:field:status> ?state }"
    },
    {
      "id": "urn:fixture:query:composed-support-status",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        },
        "lifecycle": {
          "type": "text"
        }
      },
      "support_columns": [
        "edge"
      ],
      "dependencies": [
        {
          "name": "supports",
          "definition": "urn:fixture:query:support-links",
          "root": "root",
          "projections": {
            "columns": {
              "support": "support"
            },
            "support": "edge"
          }
        },
        {
          "name": "status",
          "definition": "urn:fixture:query:root-status",
          "root": "root",
          "projections": {
            "columns": {
              "state": "state"
            }
          }
        }
      ],
      "select": "SELECT ?root ?support ?lifecycle ?edge WHERE { ?root <urn:mara:query:input:supports> ?support_row ; <urn:mara:query:input:status> ?status_row . ?support_row <urn:mara:query:column:supports:support> ?support ; <urn:mara:query:column:supports:edge> ?edge . ?status_row <urn:mara:query:column:status:state> ?lifecycle . ?support <urn:mara:field:status> ?lifecycle }"
    },
    {
      "id": "urn:fixture:query:direct-coverage",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        }
      },
      "support_columns": [
        "edge"
      ],
      "select": "SELECT ?root ?support ?edge WHERE { ?root <urn:mara:relation:supported_by> ?support . ?edge <urn:mara:query:source> ?support ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:supports> }"
    },
    {
      "id": "urn:fixture:query:design-coverage",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        }
      },
      "support_columns": [
        "edge"
      ],
      "select": "SELECT ?root ?support ?edge WHERE { ?root <urn:mara:relation:parent>+ ?design . ?design <urn:mara:relation:supported_by> ?support . ?edge <urn:mara:query:source> ?support ; <urn:mara:query:target> ?design ; <urn:mara:query:relation> <urn:mara:relation:supports> }"
    },
    {
      "id": "urn:fixture:query:direct-or-design-coverage",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        },
        "lifecycle": {
          "type": "text"
        }
      },
      "support_columns": [
        "edge"
      ],
      "dependencies": [
        {
          "name": "direct",
          "definition": "urn:fixture:query:direct-coverage",
          "root": "root",
          "projections": {
            "columns": {
              "support": "support"
            },
            "support": "edge"
          }
        },
        {
          "name": "design",
          "definition": "urn:fixture:query:design-coverage",
          "root": "root",
          "projections": {
            "columns": {
              "support": "support"
            },
            "support": "edge"
          }
        }
      ],
      "select": "SELECT ?root ?support ?lifecycle ?edge WHERE { { ?root <urn:mara:query:input:direct> ?direct_row . ?direct_row <urn:mara:query:column:direct:support> ?support ; <urn:mara:query:column:direct:edge> ?edge . ?support <urn:mara:field:status> ?lifecycle } UNION { ?root <urn:mara:query:input:design> ?design_row . ?design_row <urn:mara:query:column:design:support> ?support ; <urn:mara:query:column:design:edge> ?edge . ?support <urn:mara:field:status> ?lifecycle } }"
    },
    {
      "id": "urn:fixture:query:left-join-absence",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ],
          "optional": true
        }
      },
      "dependencies": [
        {
          "name": "status",
          "definition": "urn:fixture:query:root-status",
          "root": "root",
          "projections": {
            "columns": {
              "state": "state"
            }
          }
        },
        {
          "name": "supports",
          "definition": "urn:fixture:query:support-links",
          "root": "root",
          "projections": {
            "columns": {
              "support": "support"
            }
          }
        }
      ],
      "select": "SELECT ?root ?support WHERE { ?root <urn:mara:query:input:status> ?status_row . ?status_row <urn:mara:query:column:status:state> ?state . FILTER(sameTerm(?state, \"accepted\")) OPTIONAL { ?root <urn:mara:query:input:supports> ?support_row . ?support_row <urn:mara:query:column:supports:support> ?support } }"
    },
    {
      "id": "urn:fixture:query:parameterized-status",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "wanted": {
          "type": "text",
          "required": true
        }
      },
      "select": "SELECT ?root ?state WHERE { ?root <urn:mara:field:status> ?state . FILTER(sameTerm(?state, ?wanted)) }"
    },
    {
      "id": "urn:fixture:query:forwarded-status",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "filter_state": {
          "type": "text",
          "required": true
        }
      },
      "dependencies": [
        {
          "name": "status",
          "definition": "urn:fixture:query:parameterized-status",
          "root": "root",
          "parameters": {
            "wanted": "filter_state"
          },
          "projections": {
            "columns": {
              "state": "state"
            }
          }
        }
      ],
      "select": "SELECT ?root ?state WHERE { ?root <urn:mara:query:input:status> ?status_row . ?status_row <urn:mara:query:column:status:state> ?state }"
    },
    {
      "id": "urn:fixture:query:title-alias-collisions",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "support"
      ],
      "columns": {
        "collision": {
          "type": "item",
          "flavours": [
            "support"
          ]
        }
      },
      "select": "SELECT ?root ?collision WHERE { ?root <urn:mara:query:nfc-casefold:field:alias> ?normalized . ?collision <urn:mara:query:nfc-casefold:title> ?normalized }"
    },
    {
      "id": "urn:fixture:query:decomposition-or-supersession",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "member": {
          "type": "item",
          "flavours": [
            "subject"
          ]
        }
      },
      "select": "SELECT ?root ?member WHERE { { ?root <urn:mara:relation:decomposes_to>+ ?member } UNION { ?root <urn:mara:relation:supersedes>+ ?member } FILTER(!sameTerm(?root, ?member)) }"
    },
    {
      "id": "urn:fixture:facts:verifications",
      "required_fact_sources": [
        "documents",
        "external"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "candidate": {
          "type": "text"
        },
        "context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "external_facts": [
        {
          "input": "reported",
          "keys": [
            "verification",
            "candidate",
            "context"
          ],
          "fields": {
            "state": "state"
          },
          "missing": {
            "state": {
              "type": "text",
              "value": "missing"
            }
          }
        }
      ],
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?verification ?candidate ?context ?edge WHERE {\n  ?root r:requires_verification ?verification .\n  ?edge <urn:mara:query:source> ?root ;\n        <urn:mara:query:target> ?verification ;\n        <urn:mara:query:relation> r:requires_verification .\n  ?verification f:status ?vstatus .\n  FILTER(sameTerm(?vstatus, \"accepted\"))\n}",
      "support_columns": [
        "edge"
      ]
    },
    {
      "id": "urn:fixture:facts:validation",
      "required_fact_sources": [
        "documents",
        "external"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "candidate": {
          "type": "text"
        },
        "context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        },
        "members": {
          "type": "integer"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "external_facts": [
        {
          "input": "reported",
          "keys": [
            "verification",
            "candidate",
            "context"
          ],
          "fields": {
            "state": "state"
          },
          "missing": {
            "state": {
              "type": "text",
              "value": "missing"
            }
          }
        }
      ],
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?verification ?candidate ?context ?edge WHERE {\n  ?root r:requires_verification ?verification .\n  ?edge <urn:mara:query:source> ?root ;\n        <urn:mara:query:target> ?verification ;\n        <urn:mara:query:relation> r:requires_verification .\n  ?verification f:status ?vstatus .\n  FILTER(sameTerm(?vstatus, \"accepted\"))\n}",
      "aggregate": {
        "group_by": [
          "candidate",
          "context"
        ],
        "rank": "state",
        "precedence": [
          {
            "type": "text",
            "value": "error"
          },
          {
            "type": "text",
            "value": "fail"
          },
          {
            "type": "text",
            "value": "missing"
          },
          {
            "type": "text",
            "value": "inconclusive"
          },
          {
            "type": "text",
            "value": "pending"
          },
          {
            "type": "text",
            "value": "pass"
          }
        ],
        "retain": [
          "verification"
        ],
        "count": "members",
        "empty": {
          "type": "text",
          "value": "missing"
        }
      },
      "support_columns": [
        "edge"
      ]
    },
    {
      "id": "urn:fixture:facts:risk",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "likelihood": {
          "type": "integer"
        },
        "consequence": {
          "type": "integer"
        },
        "score": {
          "type": "integer"
        },
        "band": {
          "type": "text"
        }
      },
      "lookups": [
        {
          "mapping": "risk_matrix",
          "keys": [
            "likelihood",
            "consequence"
          ],
          "output": "score"
        },
        {
          "mapping": "risk_band",
          "keys": [
            "score"
          ],
          "output": "band"
        }
      ],
      "select": "PREFIX f: <urn:mara:field:>\nSELECT ?root ?likelihood ?consequence WHERE {\n  ?root f:likelihood ?likelihood ; f:consequence ?consequence\n}"
    },
    {
      "id": "urn:fixture:facts:composed",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "selected_candidate": {
          "type": "text"
        },
        "selected_context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "facts_columns": [
        "child_facts"
      ],
      "dependencies": [
        {
          "name": "child",
          "definition": "urn:fixture:facts:verifications",
          "root": "root",
          "parameters": {
            "candidate": "candidate",
            "context": "context"
          },
          "projections": {
            "columns": {
              "verification": "verification",
              "candidate": "candidate",
              "context": "context",
              "state": "state"
            },
            "facts": "child_facts"
          }
